function codexIconSvg(name) {
  let nodes = codexIconNodes[name];
  if (!nodes) {
    console.error(`[codex-webui] unknown icon "${name}", falling back to question mark`);
    nodes = codexIconNodes.question;
  }
  return `<svg viewBox="0 0 24 24" aria-hidden="true">${nodes}</svg>`;
}
function codexIcon(name, className = "") {
  return `<span class="icon-slot${className ? ` ${className}` : ""}">${codexIconSvg(name)}</span>`;
}
function hydrateCodexIcons(root = document) {
  for (const node of root.querySelectorAll("[data-icon]"))
    node.innerHTML = codexIconSvg(node.dataset.icon);
}

