addEventListener("keydown", (e) => {
  if (e.target instanceof Element && e.target.closest(".terminal-host"))
    return;
  if (e.key === "Escape") {
    if ($3("#imageViewer").open) {
      e.preventDefault();
      closeImageViewer();
      return;
    }
    if ($3("#folderDialog").open || $3("#fullAccessDialog").open)
      return;
    if (e.defaultPrevented)
      return;
    if (!$3("#sidebarSearchPanel").hidden) {
      e.preventDefault();
      setSidebarSearchOpen(false);
      return;
    }
    if (!$3("#sidebarHelpMenu").hidden) {
      e.preventDefault();
      setSidebarHelpOpen(false);
      return;
    }
    if ($3("#settingsDialog").open) {
      e.preventDefault();
      closeSettings();
      return;
    }
    closeModelMenu();
    closePermissionMenu();
    toggleAccountMenu(false);
    if (document.body.classList.contains("side-panel-open"))
      setSidePanelOpen(false);
    else if (document.body.classList.contains("summary-panel-open"))
      setSummaryPanelOpen(false);
  }
  if ((e.metaKey || e.ctrlKey) && e.key === "k") {
    e.preventDefault();
    startNewTask();
  }
  if ((e.metaKey || e.ctrlKey) && e.key === "b") {
    e.preventDefault();
    $3("#toggleSidebar").click();
  }
  if ((e.metaKey || e.ctrlKey) && e.key === "j") {
    e.preventDefault();
    $3("#toggleBottomPanel").click();
  }
});
