async function boot() {
  const savedProject = localStorage.getItem("codex-webui-project");
  syncSidebarLayout();
  syncPermissionControl();
  try {
    state.config = await fetch("/api/config").then((r) => r.json());
  } catch {}
  if (state.config.projectless || savedProject === "~")
    setProjectless();
  else
    setWorkspace(savedProject || state.config.defaultCwd || ".");
  refreshComposerPlaceholder();
  const initialSettingsPage = settingsRoutePage();
  if (initialSettingsPage)
    showSettings(initialSettingsPage, { updateRoute: false });
  connect();
}
